export const rect=(x,y,w,h,fill,stroke='#677468',sw=.025,rx=.04)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>`;
export function glyph(kind,w,l){const k=OBJECTS[kind],col=k?.color||'#c4b495';let out='';const line=(x1,y1,x2,y2,s='#8b9587',sw=.018)=>`<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="${s}" stroke-width="${sw}"/>`;const circle=(x,y,r,fill,stroke='#7d9180')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width=".018"/>`;
if(kind==='sofa'){out+=rect(0,0,w,l,col,'#8e9d7f',.026,.12)+rect(.12,.1,w-.24,l*.22,'#d1d9bd','#98a98c',.016,.07);for(let i=0;i<3;i++)out+=rect(.18+i*(w-.36)/3,l*.37,(w-.42)/3,l*.48,'#c1ceab','#98ab89',.016,.06);out+=rect(.025,.22,.16,l-.25,'#adbd94','#8da17e',.018,.06)+rect(w-.185,.22,.16,l-.25,'#adbd94','#8da17e',.018,.06);}
else if(kind==='bed'){out+=rect(0,0,w,l,'#b4b4a2','#839284',.025,.04)+rect(.06,.08,w-.12,l-.13,'#e8e9df','#aab4a5',.02,.06)+rect(.08,l*.33,w-.16,l*.63,'#d1d9d2','#a2b2a4',.018,.04)+rect(.15,.17,w*.35,l*.18,'#faf9ed','#b4bbab',.015,.06)+rect(w*.54,.17,w*.35,l*.18,'#faf9ed','#b4bbab',.015,.06)+line(.1,l*.43,w-.1,l*.43,'#b2c1b1',.035);}
else if(kind==='table'){out+=rect(.12,0,w*.27,.19,'#ddd9c7','#a6a68e',.018,.07)+rect(w*.62,0,w*.27,.19,'#ddd9c7','#a6a68e',.018,.07)+rect(.12,l-.19,w*.27,.19,'#ddd9c7','#a6a68e',.018,.07)+rect(w*.62,l-.19,w*.27,.19,'#ddd9c7','#a6a68e',.018,.07)+rect(0,.12,w,l-.24,col,'#9b876a',.025,.09)+circle(w*.66,l*.48,.095,'#e8dfc4')+circle(w*.34,l*.5,.07,'#8f9c6d');}
else if(kind==='coffee'||kind==='island'){out+=rect(0,0,w,l,col,'#a08c70',.022,.08)+rect(.07,.07,w-.14,l-.14,'#dac6a4','#bba888',.012,.05)+circle(w*.72,l*.45,Math.min(w,l)*.16,'#e6e5d1');}
else if(kind==='kitchen'){out+=rect(0,0,w,l,col,'#819079',.025,.025);for(let x=.6;x<w;x+=.6)out+=line(x,.02,x,l-.02);out+=rect(.1,.09,Math.min(.55,w*.3),l-.18,'#ccd5cd','#7e988b',.018,.07)+rect(w*.63,.07,w*.29,l-.14,'#465a4d','#7b897b',.018,.03);for(const a of [.7,.85])for(const b of [.3,.7])out+=circle(w*a,l*b,.045,'#859580','#a9b29a');}
else if(kind==='shower'){out+=rect(0,0,w,l,'#d5e5dc','#81a99a',.025,.02)+line(.1,.1,w-.1,l-.1,'#b5d1c2')+line(w-.1,.1,.1,l-.1,'#b5d1c2')+circle(w*.5,l*.5,.04,'#9daea0')+rect(w*.3,0,w*.4,.05,'#94b6a7','#7f9e8e',.015);}
else if(kind==='wc'){out+=rect(0,0,w,l*.28,'#eeefe3','#a7b6a0',.018,.03)+`<ellipse cx="${w/2}" cy="${l*.6}" rx="${w*.44}" ry="${l*.35}" fill="#f6f5e9" stroke="#a7b6a0" stroke-width=".02"/><ellipse cx="${w/2}" cy="${l*.57}" rx="${w*.26}" ry="${l*.2}" fill="#dfe5d8" stroke="#b3beab" stroke-width=".015"/>`;}
else if(kind==='sink'){out+=rect(0,0,w,l,col,'#a8977c',.02,.035)+rect(w*.18,l*.13,w*.64,l*.7,'#f3f2e6','#b4b9aa',.02,.1)+circle(w*.5,l*.52,.024,'#94a28d')+line(w*.5,.02,w*.5,l*.22,'#708d82',.035);}
else if(kind==='plant'){out+=circle(w/2,l/2,Math.min(w,l)*.46,'#c6b695','#ac9b7a');for(let i=0;i<7;i++)out+=`<ellipse cx="${w/2}" cy="${l*.32}" rx="${w*.15}" ry="${l*.3}" fill="${i%2?'#96ac72':'#78935d'}" transform="rotate(${i*51} ${w/2} ${l/2})"/>`;out+=circle(w/2,l/2,.04,'#adc28e');}
else if(kind==='shelf'){out+=rect(0,0,w,l,'#9da99a','#6f8374',.025,.025);for(let x=.08;x<w-.2;x+=.62){out+=rect(x,.08,Math.min(.52,w-x-.06),l-.16,'#c7baa1','#a19c84',.018,.02)+line(x+.12,l*.4,x+.35,l*.4,'#a19c84');}}
else if(kind==='printer'){out+=rect(0,0,w,l,'#5d756b','#435d52',.025,.05)+rect(.08,.1,w-.16,l-.18,'#a9bdb0','#7f9c8a',.02,.02)+line(w*.5,.1,w*.5,l-.08,'#486858',.04)+rect(w*.35,l*.4,w*.3,l*.3,'#c5d7ae','#668b6d',.02,.02);}
else if(kind==='car'){out+=rect(0,0,w,l,'#bdc7c6','#83968a',.035,.3)+rect(w*.12,l*.2,w*.76,l*.22,'#8eaaa4','#6d8b83',.02,.1)+rect(w*.12,l*.66,w*.76,l*.15,'#8eaaa4','#6d8b83',.02,.09)+rect(w*.15,l*.44,w*.7,l*.19,'#d3dbd4','#a6b6a8',.02,.09);}
else if(kind==='stairs'){out+=rect(0,0,w,l,'#d2c6ac','#9a8d71',.025,.02);for(let i=1;i<12;i++)out+=line(0,l*i/12,w,l*i/12,'#9c9279',.018);out+=line(w*.5,l*.15,w*.5,l*.8,'#5c7555',.035)+line(w*.5,l*.8,w*.32,l*.65,'#5c7555',.035)+line(w*.5,l*.8,w*.68,l*.65,'#5c7555',.035);}
else if(kind==='desk'||kind==='workbench'){out+=rect(0,0,w,l,col,'#9c896b',.025,.04)+rect(w*.23,l*.12,w*.38,l*.32,'#82978b','#597868',.018,.02)+line(w*.42,l*.43,w*.42,l*.61,'#738c78',.03)+rect(w*.7,l*.26,w*.15,l*.45,'#e3ddc3','#ab9e80',.015,.02);}
else{out+=rect(0,0,w,l,col,'#92a18d',.025,.025)+line(w/2,.025,w/2,l-.025)+line(w*.38,l*.45,w*.38,l*.65)+line(w*.62,l*.45,w*.62,l*.65);}
return out;}
export function thumb(kind,isRoom=false){if(isRoom){const k=ROOM_TYPES[kind];const g={living:'sofa',kitchen:'kitchen',bed:'bed',bath:'shower',office:'desk',hall:'wardrobe',other:'table'}[kind];return `<svg viewBox="-.15 -.15 3.3 2.3"><rect x="0" y="0" width="3" height="2" rx=".04" fill="${k.color}" stroke="#a7b294" stroke-width=".05"/><path d="M0 2V0H3V2" fill="none" stroke="#73866e" stroke-width=".09"/><g transform="translate(.55 .36)">${glyph(g,1.85,1.1)}</g></svg>`;}const k=OBJECTS[kind];return `<svg viewBox="-.25 -.25 ${k.w+.5} ${k.l+.5}">${glyph(kind,k.w,k.l)}</svg>`;}
export const line=(x1,y1,x2,y2,stroke,width=.02,extra='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${stroke}" stroke-width="${width}" ${extra}/>`;
export const text=(x,y,t,size=.22,fill='#657c60',extra='')=>`<text x="${x}" y="${y}" font-family="Inter,Segoe UI,system-ui,sans-serif" font-size="${size}" fill="${fill}" ${extra}>${esc(t)}</text>`;
export function objectGlyph(o){const q=Math.round((o.rotation||0)/90)%4;if(q===1)return `<g transform="translate(${o.w} 0) rotate(90)">${glyph(o.kind,o.l,o.w)}</g>`;if(q===2)return `<g transform="translate(${o.w} ${o.l}) rotate(180)">${glyph(o.kind,o.w,o.l)}</g>`;if(q===3)return `<g transform="translate(0 ${o.l}) rotate(270)">${glyph(o.kind,o.l,o.w)}</g>`;return glyph(o.kind,o.w,o.l);}
